<?php
namespace App\Http\Middleware;use Closure;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Symfony\Component\HttpFoundation\Response;
class AuthenticateDeveloperApiKey{public function handle(Request $request,Closure $next,?string $scope=null):Response{$started=microtime(true);$token=$request->bearerToken();abort_unless($token&&str_starts_with($token,'pb_'),401,'A valid bearer token is required.');$key=DB::table('developer_api_keys')->where('token_hash',hash('sha256',$token))->whereNull('revoked_at')->where(fn($q)=>$q->whereNull('expires_at')->orWhere('expires_at','>',now()))->first();abort_unless($key,401,'API key is invalid, expired, or revoked.');$scopes=json_decode($key->scopes,true)?:[];abort_unless(!$scope||in_array($scope,$scopes,true),403,'API key scope is insufficient.');$request->attributes->set('developer_api_key',$key);$response=$next($request);DB::table('developer_api_keys')->where('id',$key->id)->update(['last_used_at'=>now()]);DB::table('api_request_logs')->insert(['developer_api_key_id'=>$key->id,'method'=>$request->method(),'path'=>substr($request->path(),0,512),'status_code'=>$response->getStatusCode(),'duration_ms'=>(int)((microtime(true)-$started)*1000),'ip_hash'=>hash('sha256',(string)$request->ip().config('app.key')),'created_at'=>now()]);return $response;}}
